def needverb(ttype):
    if 'clean' in ttype:
        return 'clean'
    if 'heat' in ttype:
        return 'heat'
    if 'cool' in ttype:
        return 'cool'
    return ''

def hook(ctx, nb):
    ttype = str(val(ctx, 'task', 'task_type', '')).lower()
    target = str(val(ctx, 'task', 'target_type', '')).lower()
    dest = str(val(ctx, 'task', 'destination_type', '')).lower()
    verb = needverb(ttype)
    if not verb:
        nb['transformed'] = True
    if not target:
        return None
    act = str(val(ctx, 'action', 'final_action') or val(ctx, 'action', 'normalized') or val(ctx, 'action', 'raw') or '').lower()
    obs = str(ctx.get('observation') or '').lower()
    inv = val(ctx, 'world', 'inventory', '')
    invs = ''
    if isinstance(inv, list) or isinstance(inv, tuple):
        invs = ' '.join([str(x).lower() for x in inv])
    else:
        invs = str(inv).lower()
    empty_inv = (not invs) or invs in ('none', '[]') or ('nothing' in invs and 'not carrying' in invs)
    carrying_target = bool(target and target in invs and not empty_inv)
    carrying_any = bool(invs and not empty_inv)
    wrong_inv = bool(target and not empty_inv and not carrying_target and not carrying_any == False)
    adm = ctx.get('admissible') or []
    take_target = False
    put_target = False
    trans_ready = False
    for a in adm:
        al = str(a).lower()
        if target and al.startswith('take ' + target + ' '):
            take_target = True
        if target and dest and al.startswith('put ' + target + ' ') and dest in al:
            put_target = True
        if verb and target and al.startswith(verb + ' ') and target in al:
            trans_ready = True
    pc = val(ctx, 'world', 'placed_count', nb.get('placed_count', 0))
    if isinstance(pc, str) and pc.isdigit():
        pc = int(pc)
    if not isinstance(pc, int):
        pc = 0
    if act.startswith('put ' + target + ' ') and dest and dest in act and 'nothing happens' not in obs and 'can\'t put' not in obs and 'cannot put' not in obs:
        pc = max(pc, nb.get('placed_count', 0) + 1)
    if target and act.startswith('put ' + target + ' ') and dest and dest in act and 'nothing happens' in obs and 'can\'t put' not in act and 'cannot put' not in act and 'put' not in obs:
        pc = max(0, pc - 1)
    items = val(ctx, 'world', 'placed_items', [])
    if isinstance(items, str):
        items = [items]
    locs = val(ctx, 'world', 'placed_locations', [])
    if isinstance(locs, str):
        locs = [locs]
    if target and act.startswith('put ' + target + ' ') and dest and dest in act and 'nothing happens' not in obs and 'can\'t put' not in obs and 'cannot put' not in obs:
        item = act[4:]
        for sep in [' from ', ' in ', ' on ']:
            if sep in item:
                item = item.split(sep)[0]
        if item and item not in nb.get('placed_items', []):
            nb.setdefault('placed_items', []).append(item)
        loc = ''
        for sep in [' from ', ' in ', ' on ']:
            if sep in act:
                loc = act.split(sep)[1]
        if loc and loc not in nb.get('placed_locations', []):
            nb.setdefault('placed_locations', []).append(loc)
    need = 2 if 'two' in ttype else 1
    if pc >= need:
        stage = 'done'
    elif wrong_inv:
        stage = 'wrong_inventory'
    elif carrying_target:
        if verb and not nb.get('transformed'):
            stage = 'transform'
        elif put_target:
            stage = 'put_target'
        else:
            stage = 'go_destination'
    elif take_target or val(ctx, 'world', 'target_found', False) or val(ctx, 'world', 'target_location', ''):
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = ttype
    nb['verb'] = verb
    nb['need_count'] = need
    nb['placed_count'] = pc
    nb['placed_items'] = nb.get('placed_items', [])
    nb['placed_locations'] = nb.get('placed_locations', [])
    nb['target_take_available'] = take_target
    nb['transform_ready'] = trans_ready
    nb['put_available'] = put_target
    nb['carrying_target'] = carrying_target
    nb['wrong_inventory'] = wrong_inv
    return None

