def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or str(val(ctx, 'task', 'target_type', ''))
    dest = nb.get('destination_type') or str(val(ctx, 'task', 'destination_type', ''))
    verb = nb.get('verb') or needverb(val(ctx, 'task', 'task_type', ''))
    tool = 'the right tool'
    if verb == 'clean':
        tool = 'a sinkbasin'
    if verb == 'heat':
        tool = 'a microwave'
    if verb == 'cool':
        tool = 'a fridge'
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target object. Put it back if possible, then search for the requested ' + target + '; do not place it at the ' + dest + '.'
    elif stage == 'find_target' and 'two' in (nb.get('task_type') or '') and nb.get('placed_count', 0) > 0:
        msg = 'Find another ' + target + ' different from the one already placed; keep using the same ' + dest + ' and do not take back placed items.'
    elif stage == 'take_target' and nb.get('target_take_available') and target:
        msg = 'A requested ' + target + ' is available here; take it instead of continuing to search.'
    elif stage == 'transform' and verb and target:
        msg = 'Before placing, ' + verb + ' the ' + target + ' using ' + tool + '.'
    elif stage == 'put_target' and target and dest:
        msg = 'You have the ' + target + '; put it at the ' + dest + ' and do not pick it back up.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    seen = nb.get('seen_hint') or {}
    if key in seen or seen.get(key, 0) >= 3:
        return None
    seen[key] = seen.get(key, 0) + 1
    nb['seen_hint'] = seen
    nb['last_hint'] = key
    return {'message': msg}

