    verb = nb.get('verb') or needverb(ttype)
    if not target or not verb:
        return None
    act = str(val(ctx, 'action', 'final_action') or val(ctx, 'action', 'normalized') or val(ctx, 'action', 'raw') or ctx.get('output') or '').lower()
    if not act:
