        invs = str(inv).lower()
    carrying_target = bool(target and target in invs)
    carrying_any = bool(invs and not (not invs or invs in ('none', '[]') or 'nothing' in invs and 'not carrying' in invs))
    wrong_inv = bool(carrying_any and not carrying_target)
    if wrong_inv and (act.startswith('put ') or act.startswith('go to ')) and target and dest and dest in act:
        return {'kind': 'block_and_prompt', 'message': 'You are carrying a non-target object. Recover and find the requested ' + target + ' before placing anything at the ' + dest + '.'}
    if 'two' in ttype and target and dest and act.startswith('take ' + target + ' ') and dest in act and nb.get('placed_count', 0) > 0:
        return {'kind': 'block_and_prompt', 'message': 'Do not take back a target already placed at the destination; find another ' + target + ' instead.'}
    if not carrying_target and target and act.startswith('put ' + target + ' ') and dest and dest in act and nb.get('stage') == 'take_target':
        return {'kind': 'block_and_prompt', 'message': 'A requested ' + target + ' is available; take it before placing it.'}
    if carrying_target and verb and not nb.get('transformed') and target and act.startswith(verb + ' ') and target not in act:
        return {'kind': 'block_and_prompt', 'message': 'This transform does not apply to the target. Use the required transform for the ' + target + ', then place it at the ' + dest + '.'}
    return None
